import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import CanvasPage from "./CanvasPage.js";

describe("CanvasPage", () => {
  it("renders its content in a section named by its heading", () => {
    render(
      <CanvasPage aria-labelledby="page-title">
        <h1 id="page-title">Login</h1>
        <p>Demo login.</p>
      </CanvasPage>,
    );
    expect(screen.getByRole("region", { name: "Login" })).toContainElement(
      screen.getByText("Demo login."),
    );
  });

  it("passes native props through and merges a consumer className after its own", () => {
    render(
      <CanvasPage className="is-quiet" data-testid="page">
        <p>Content</p>
      </CanvasPage>,
    );
    expect(screen.getByTestId("page").className).toBe(
      "ds canvas-page is-quiet",
    );
  });
});
